export type DonutSlice = {
  id: string;
  name: string;
  sharePct: number;
  color: string;
};

export function ladderFor(id: PerimeterId): LadderRow[] {
  switch (id) {
    case "gerd":
      return GERD_LADDER;
    case "pubs":
      return PUB_LADDER;
    case "cet":
      return CET_AI_LADDER;
    case "kti":
      return KTI_LADDER;
  }
}

export function curveFor(id: PerimeterId): CurvePoint[] {
  switch (id) {
    case "gerd":
      return GERD_CURVE;
    case "pubs":
      return PUB_CURVE;
    case "cet":
      return [
        { rank: 0, label: "0", sharePct: 0, equalPct: 0 },
        { rank: 1, label: "Top-1", sharePct: 75, equalPct: 25 },
        { rank: 2, label: "Top-2", sharePct: 87, equalPct: 50 },
        { rank: 3, label: "Top-3", sharePct: 92, equalPct: 75 },
        { rank: 4, label: "All", sharePct: 100, equalPct: 100 },
      ];
    case "kti":
      return KTI_CURVE;
  }
}

export function donutFor(id: PerimeterId): DonutSlice[] {
  return ladderFor(id).map((r) => ({
    id: r.id,
    name: r.short,
    sharePct: r.sharePct,
    color: r.color,
  }));
}

export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

export function fmtHhi(n: number): string {
  return n.toLocaleString("en-US");
}

export function fmtBn(n: number): string {
  return `$${n.toFixed(0)}B`;
}

