        { rank: 4, label: "All", sharePct: 100, equalPct: 100 },
      ];
    case "kti":
      return KTI_CURVE;
  }
}

export function donutFor(id: PerimeterId): DonutSlice[] {
  return ladderFor(id).map((r) => ({
    id: r.id,
    name: r.short,
    sharePct: r.sharePct,
    color: r.color,
  }));
}

export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

export function fmtHhi(n: number): string {
  return n.toLocaleString("en-US");
}

export function fmtBn(n: number): string {
  return `$${n.toFixed(0)}B`;
}

