"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CET_FIELDS,
  CONCENTRATION_DELTAS,
  CONCENTRATION_PATH,
  FRAME_SENSITIVITY,
  HEADLINE,
  HHI_BY_LENS,
  SCOREBOARD,
  SECTOR_ENGINE,
  SOURCE_NOTE,
  SOURCES,
  VOLUME_IMPACT,
  curveFor,
  donutFor,
  fmtBn,
  fmtHhi,
  fmtPct,
  fmtPp,
  ladderFor,
  type PerimeterId,
} from "@/data/measurement-science-concentration-2026q3-data";

// viz-types: scoreboard bars, prior???Q3 delta dumbbells, Lorenz area+line, ranked ladder bars, frame sensitivity bars, HHI bars, sector engine bars, path multi-line, donut, CET field bars, volume??impact scatter | layout: default

type ViewId = "scoreboard" | "ladder" | "frames" | "impact";
type LadderMetric = "sharePct" | "cumulativePct";
type ScoreMetric = "top1Pct" | "top3Pct";
type PathMetric = "gerd" | "pubs";

const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const VIOLET = "#8b5cf6";
const SLATE = "#94a3b8";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "bg-transparent text-slate-700 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function MeasurementScienceConcentration2026q3Dashboard() {
  const [view, setView] = useState<ViewId>("scoreboard");
  const [perimeter, setPerimeter] = useState<PerimeterId>("gerd");
  const [ladderMetric, setLadderMetric] = useState<LadderMetric>("sharePct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [pathMetric, setPathMetric] = useState<PathMetric>("gerd");
  const [scoreMetric, setScoreMetric] = useState<ScoreMetric>("top1Pct");

  const ladder = useMemo(() => {
    const rows = [...ladderFor(perimeter)];
    if (ladderMetric === "sharePct") {
      return rows.sort((a, b) => b.sharePct - a.sharePct);
    }
    return rows.sort((a, b) => b.cumulativePct - a.cumulativePct);
  }, [perimeter, ladderMetric]);

  const curve = useMemo(() => curveFor(perimeter), [perimeter]);
  const donut = useMemo(() => donutFor(perimeter), [perimeter]);

  const scoreboardBars = useMemo(
    () =>
      SCOREBOARD.map((r) => ({
        ...r,
        short: r.label.replace(" (PPP)", "").replace(" priority patents", ""),
      })),
    [],
  );

  const deltaBars = useMemo(
    () =>
      CONCENTRATION_DELTAS.map((d) => ({
        ...d,
        short: d.label.replace("GERD ", "").replace("Pubs ", "").replace("CET AI ", ""),
      })),
    [],
  );

  const scatter = useMemo(
    () =>
      VOLUME_IMPACT.map((r) => ({
        ...r,
        x: r.pubSharePct,
        y: r.hcaRatePct,
        z: Math.max(40, (r.gerdSharePct ?? 4) * 6),
      })),
    [],
  );

  const sectorBars = useMemo(
    () =>
      SECTOR_ENGINE.map((s) => ({
        ...s,
        display: s.unit === "pct" ? s.value : s.value,
        axisLabel: s.short,
      })),
    [],
  );

  const perimeterLabel =
    SCOREBOARD.find((s) => s.id === perimeter)?.label ?? perimeter;

  return (
    <div
      className="space-y-6"
      data-viz="measurement-science-concentration-2026q3"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-6 text-white shadow-sm sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-wider text-amber-300">
          Measurement &amp; science ??? Q3 2026 concentration lens
        </p>
        <h2 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          Top-1 gap thins to {fmtPct(HEADLINE.gerdGapPp, 1)} ?? US+China still{" "}
          {fmtPct(HEADLINE.gerdUsChinaPct, 1)}; AI patents hold{" "}
          {fmtPct(HEADLINE.cetAiTop1Pct)}
        </h2>
        <p className="mt-3 max-w-3xl text-sm leading-relaxed text-slate-300">
          Q3 OECD/AAAS restatement softens the GERD knife-edge (
          <span className="text-rose-300">
            China {fmtPct(HEADLINE.gerdTop1Pct, 1)}
          </span>{" "}
          vs{" "}
          <span className="text-sky-300">
            US {fmtPct(HEADLINE.gerdUsPct, 1)}
          </span>
          ) without breaking the duopoly. EXR flips Top-1; non-OECD residual
          prints China at{" "}
          <span className="text-pink-300">
            {fmtPct(HEADLINE.chinaNonOecdSharePct, 1)}
          </span>
          . Publications Top-3 and CET AI volume stay carried extremes.
        </p>
        <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {[
            {
              label: "GERD Top-1",
              value: fmtPct(HEADLINE.gerdTop1Pct, 1),
              sub: `${fmtPp(HEADLINE.gerdTop1DeltaPp)} vs NSF`,
            },
            {
              label: "China???US gap",
              value: fmtPct(HEADLINE.gerdGapPp, 1),
              sub: `${fmtPp(HEADLINE.gerdGapDeltaPp)} vs prior`,
            },
            {
              label: "US+China",
              value: fmtPct(HEADLINE.gerdUsChinaPct, 1),
              sub: "GERD PPP duopoly",
            },
            {
              label: "AI patents Top-1",
              value: fmtPct(HEADLINE.cetAiTop1Pct),
              sub: HEADLINE.cetAiTop1Label,
            },
          ].map((k) => (
            <div
              key={k.label}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-3"
            >
              <p className="text-[11px] uppercase tracking-wide text-slate-400">
                {k.label}
              </p>
              <p className="mt-1 text-xl font-bold tabular-nums">{k.value}</p>
              <p className="text-xs text-slate-400">{k.sub}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-4">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "scoreboard", label: "Scoreboard" },
            { id: "ladder", label: "Concentration ladder" },
            { id: "frames", label: "Frames & engines" },
            { id: "impact", label: "Volume vs impact" },
          ]}
        />
      </div>

      {view === "scoreboard" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Top-1 vs Top-3 by perimeter"
            subtitle="Toggle which meter ranks the four perimeters"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Meter"
                value={scoreMetric}
                onChange={setScoreMetric}
                options={[
                  { id: "top1Pct", label: "Top-1" },
                  { id: "top3Pct", label: "Top-3" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={scoreboardBars}
                  margin={{ top: 8, right: 12, left: 0, bottom: 48 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="id"
                    tick={{ fontSize: 11 }}
                    interval={0}
                    angle={-20}
                    textAnchor="end"
                    height={50}
                    tickFormatter={(id) =>
                      SCOREBOARD.find((s) => s.id === id)?.label.split(" ")[0] ??
                      id
                    }
                  />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v) => [
                      `${Number(v).toFixed(1)}%`,
                      scoreMetric === "top1Pct" ? "Top-1" : "Top-3",
                    ]}
                    labelFormatter={(id) =>
                      SCOREBOARD.find((s) => s.id === id)?.label ?? String(id)
                    }
                  />
                  <Bar dataKey={scoreMetric} radius={[4, 4, 0, 0]}>
                    {scoreboardBars.map((r) => (
                      <Cell key={r.id} fill={r.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Prior ??? Q3 concentration deltas"
            subtitle="NSF ~30/29 print vs OECD/AAAS 29.4/29.1 restatement"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={deltaBars}
                  layout="vertical"
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[-1, 1]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v} pp`}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={88}
                    tick={{ fontSize: 10 }}
                  />
                  <ReferenceLine x={0} stroke={SLATE} />
                  <Tooltip
                    formatter={(v) => [fmtPp(Number(v)), "?? vs prior"]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                  />
                  <Bar dataKey="deltaPp" radius={[0, 4, 4, 0]}>
                    {deltaBars.map((d) => (
                      <Cell
                        key={d.id}
                        fill={d.deltaPp < 0 ? SKY : d.deltaPp > 0 ? ROSE : SLATE}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Q3 perimeter scoreboard"
            subtitle="Restated GERD + carried pubs / CET / KTI"
          >
            <div className="overflow-x-auto">
              <table className="w-full min-w-[32rem] text-left text-sm">
                <thead>
                  <tr className="border-b border-slate-200 text-xs uppercase tracking-wide text-slate-500">
                    <th className="py-2 pr-3 font-semibold">Perimeter</th>
                    <th className="py-2 pr-3 font-semibold">Top-1</th>
                    <th className="py-2 pr-3 font-semibold">Prior Top-1</th>
                    <th className="py-2 pr-3 font-semibold">Top-3</th>
                    <th className="py-2 font-semibold">Extra</th>
                  </tr>
                </thead>
                <tbody>
                  {SCOREBOARD.map((r) => (
                    <tr key={r.id} className="border-b border-slate-100">
                      <td className="py-2.5 pr-3 font-medium text-slate-800">
                        <span
                          className="mr-2 inline-block h-2 w-2 rounded-full"
                          style={{ background: r.color }}
                        />
                        {r.label}
                      </td>
                      <td className="py-2.5 pr-3 tabular-nums text-slate-700">
                        {fmtPct(r.top1Pct, r.top1Pct % 1 ? 1 : 0)}{" "}
                        <span className="text-slate-400">({r.top1Label})</span>
                      </td>
                      <td className="py-2.5 pr-3 tabular-nums text-slate-500">
                        {r.priorTop1Pct != null
                          ? fmtPct(r.priorTop1Pct, r.priorTop1Pct % 1 ? 1 : 0)
                          : "???"}
                      </td>
                      <td className="py-2.5 pr-3 tabular-nums text-slate-700">
                        {fmtPct(r.top3Pct, r.top3Pct % 1 ? 1 : 0)}
                      </td>
                      <td className="py-2.5 text-slate-600">
                        {r.extraMetric}: {r.extraValue}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </ChartCard>

          <ChartCard
            title="Concentration path since 2000"
            subtitle="GERD Top-1 eased as China rose ??? US+China and pubs Top-3 tightened"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Series"
                value={pathMetric}
                onChange={setPathMetric}
                options={[
                  { id: "gerd", label: "GERD shares" },
                  { id: "pubs", label: "Publication shares" },
                ]}
              />
            </div>
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart
                  data={CONCENTRATION_PATH}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[20, 80]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                  />
                  {pathMetric === "gerd" ? (
                    <>
                      <Line
                        type="monotone"
                        dataKey="top1Pct"
                        name="GERD Top-1"
                        stroke={ROSE}
                        strokeWidth={2.5}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="top3Pct"
                        name="GERD Top-3"
                        stroke={AMBER}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="usChinaPct"
                        name="US+China"
                        stroke={SKY}
                        strokeWidth={2}
                        strokeDasharray="4 3"
                        dot={{ r: 3 }}
                      />
                    </>
                  ) : (
                    <>
                      <Line
                        type="monotone"
                        dataKey="pubsTop1Pct"
                        name="Pubs Top-1"
                        stroke={ROSE}
                        strokeWidth={2.5}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="pubsTop3Pct"
                        name="Pubs Top-3"
                        stroke={AMBER}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                    </>
                  )}
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "ladder" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <div className="lg:col-span-2">
            <ToggleGroup
              label="Perimeter"
              value={perimeter}
              onChange={setPerimeter}
              options={[
                { id: "gerd", label: "GERD" },
                { id: "pubs", label: "Publications" },
                { id: "cet", label: "CET AI patents" },
                { id: "kti", label: "KTI VA" },
              ]}
            />
          </div>

          <ChartCard
            title="Cumulative share vs equal split"
            subtitle={`How fast ${perimeterLabel} accumulates at the top`}
          >
            <div className="mb-3">
              <ToggleGroup
                label="Equal-split line"
                value={showEqualLine ? "on" : "off"}
                onChange={(v) => setShowEqualLine(v === "on")}
                options={[
                  { id: "on", label: "Show" },
                  { id: "off", label: "Hide" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={curve}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "sharePct" ? "Actual cumulative" : "Equal split",
                    ]}
                  />
                  <Area
                    type="monotone"
                    dataKey="sharePct"
                    fill={ROSE}
                    fillOpacity={0.25}
                    stroke={ROSE}
                    strokeWidth={2.5}
                    name="sharePct"
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalPct"
                      stroke={SLATE}
                      strokeDasharray="6 4"
                      strokeWidth={1.5}
                      dot={false}
                      name="equalPct"
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Ranked share ladder"
            subtitle="Toggle share of perimeter vs cumulative share at each rank"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Metric"
                value={ladderMetric}
                onChange={setLadderMetric}
                options={[
                  { id: "sharePct", label: "Share" },
                  { id: "cumulativePct", label: "Cumulative" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={ladder}
                  layout="vertical"
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={56}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [`${Number(v).toFixed(1)}%`, "Value"]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.name ?? ""
                    }
                  />
                  <Bar dataKey={ladderMetric} radius={[0, 4, 4, 0]}>
                    {ladder.map((r) => (
                      <Cell key={r.id} fill={r.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Share composition"
            subtitle={`${perimeterLabel} ??? residual closes the universe`}
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={donut}
                    dataKey="sharePct"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {donut.map((s) => (
                      <Cell key={s.id} fill={s.color} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v) => [`${Number(v).toFixed(1)}%`, "Share"]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Cross-perimeter HHI map"
            subtitle="CET AI and non-OECD residual dwarf GERD / pubs / KTI"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={HHI_BY_LENS}
                  margin={{ top: 8, right: 12, left: 0, bottom: 40 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="label"
                    tick={{ fontSize: 10 }}
                    interval={0}
                    angle={-18}
                    textAnchor="end"
                    height={48}
                  />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) => [fmtHhi(Number(v)), "HHI"]}
                    labelFormatter={(label) => String(label)}
                  />
                  <Bar dataKey="hhi" radius={[4, 4, 0, 0]}>
                    {HHI_BY_LENS.map((r) => (
                      <Cell key={r.id} fill={r.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "frames" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Frame sensitivity ??? China vs US GERD"
            subtitle="Official PPP keeps a fragile China Top-1; EXR flips the ranking"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={FRAME_SENSITIVITY}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 120]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <ReferenceLine
                    y={100}
                    stroke={SLATE}
                    strokeDasharray="4 4"
                    label={{
                      value: "Parity",
                      position: "insideTopRight",
                      fill: "#64748b",
                      fontSize: 11,
                    }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      `${Number(v).toFixed(0)}% of US GERD`,
                      "China",
                    ]}
                    labelFormatter={(label) => String(label)}
                  />
                  <Bar dataKey="chinaVsUsPct" radius={[4, 4, 0, 0]}>
                    {FRAME_SENSITIVITY.map((r) => (
                      <Cell key={r.id} fill={r.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-3 space-y-1 text-xs text-slate-500">
              {FRAME_SENSITIVITY.map((r) => (
                <li key={r.id}>
                  <span className="font-medium text-slate-700">{r.label}:</span>{" "}
                  Top-1 ??? {r.top1Label}. {r.note}
                </li>
              ))}
            </ul>
          </ChartCard>

          <ChartCard
            title="What drives the duopoly"
            subtitle="BERD gap vs government lead vs non-OECD residual share"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={sectorBars}
                  layout="vertical"
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="axisLabel"
                    width={72}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _, item) => {
                      const unit = item?.payload?.unit;
                      return [
                        unit === "pct"
                          ? fmtPct(Number(v), 1)
                          : fmtBn(Number(v)),
                        item?.payload?.label ?? "Value",
                      ];
                    }}
                  />
                  <Bar dataKey="display" radius={[0, 4, 4, 0]}>
                    {sectorBars.map((s) => (
                      <Cell key={s.id} fill={s.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-3 text-sm text-slate-600">
              China&apos;s business BERD edge (~{fmtBn(HEADLINE.businessBerdGapBn)})
              outweighs the US government lead (~{fmtBn(HEADLINE.govtUsLeadBn)}).
              Inside the non-OECD residual, China alone is{" "}
              {fmtPct(HEADLINE.chinaNonOecdSharePct, 1)}.
            </p>
          </ChartCard>

          <ChartCard
            title="CET China volume by field"
            subtitle="AI is the cliff; every field still shows a US citation lead"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={CET_FIELDS}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v) => [`${Number(v).toFixed(0)}%`, "China share"]}
                    labelFormatter={(label) =>
                      CET_FIELDS.find((f) => f.short === label)?.label ??
                      String(label)
                    }
                  />
                  <Bar dataKey="chinaSharePct" radius={[4, 4, 0, 0]}>
                    {CET_FIELDS.map((f) => (
                      <Cell key={f.id} fill={f.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Top-1 ?? Top-3 scatter"
            subtitle="Each point is a perimeter ??? CET AI remains the extreme"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 4, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="top1Pct"
                    name="Top-1"
                    domain={[20, 80]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-1 share",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                      fill: "#64748b",
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="top3Pct"
                    name="Top-3"
                    domain={[40, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "Top-3",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                      fill: "#64748b",
                    }}
                  />
                  <ZAxis type="number" dataKey="top3Pct" range={[80, 320]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "top1Pct" ? "Top-1" : "Top-3",
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                  />
                  <Scatter data={SCOREBOARD} fill={AMBER}>
                    {SCOREBOARD.map((p) => (
                      <Cell key={p.id} fill={p.color} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "impact" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Publication share ?? HCA rate"
            subtitle="Bubble size ??? GERD share ??? volume does not equal citation rate"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 4, bottom: 12 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Pub share"
                    domain={[0, 35]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "S&E publication share",
                      position: "insideBottom",
                      offset: -4,
                      fontSize: 11,
                      fill: "#64748b",
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="HCA rate"
                    domain={[0.8, 2]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "HCA rate",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                      fill: "#64748b",
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => {
                      if (name === "x") return [`${Number(v).toFixed(0)}%`, "Pub share"];
                      if (name === "y") return [`${Number(v).toFixed(1)}%`, "HCA rate"];
                      return [String(v), String(name)];
                    }}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.name ?? ""
                    }
                  />
                  <Scatter data={scatter} fill={VIOLET}>
                    {scatter.map((p) => (
                      <Cell key={p.id} fill={p.color} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Volume???impact reading"
            subtitle="Why Top-1 on papers is not Top-1 on influence"
          >
            <ul className="space-y-3 text-sm leading-relaxed text-slate-700">
              <li>
                <span className="font-semibold text-slate-900">China</span>{" "}
                prints {fmtPct(HEADLINE.pubsTop1Pct)} of S&amp;E articles and{" "}
                {fmtPct(HEADLINE.gerdTop1Pct, 1)} of GERD, but HCA rate sits near{" "}
                {fmtPct(HEADLINE.chinaHcaRatePct, 1)} ??? mid-pack, not frontier
                monopoly.
              </li>
              <li>
                <span className="font-semibold text-slate-900">United States</span>{" "}
                holds only {fmtPct(HEADLINE.pubsUsPct)} of papers yet{" "}
                {fmtPct(HEADLINE.usHcaRatePct, 1)} HCA rate and still leads KTI
                VA at {fmtPct(HEADLINE.ktiTop1Pct)}.
              </li>
              <li>
                <span className="font-semibold text-slate-900">CET AI patents</span>{" "}
                remain the volume cliff ({fmtPct(HEADLINE.cetAiTop1Pct)} China)
                while NSF Translation still flags US citation leadership across
                fields.
              </li>
              <li>
                Q3&apos;s contribution is the{" "}
                <span className="font-semibold text-slate-900">
                  fragile GERD Top-1
                </span>
                : gap {fmtPct(HEADLINE.gerdGapPp, 1)} under PPP, flipped under
                EXR, while US+China still clear {fmtPct(HEADLINE.gerdUsChinaPct, 1)}.
              </li>
            </ul>
          </ChartCard>
        </div>
      )}

      <div className="rounded-xl border border-slate-200 bg-slate-50 px-5 py-4 text-xs leading-relaxed text-slate-600">
        <p className="font-semibold text-slate-800">Sources &amp; caveats</p>
        <p className="mt-1">{SOURCE_NOTE}</p>
        <ul className="mt-2 list-inside list-disc space-y-0.5">
          {SOURCES.map((s) => (
            <li key={s.url}>
              <a
                href={s.url}
                className="text-sky-700 underline-offset-2 hover:underline"
              >
                {s.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

